// Cosmos DB context demonstrating EF Core 9 breaking-change fixes
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "CatalogDb");

        // Breaking Change #1: Cosmos sync I/O now throws by default in EF Core 9.
        // Fix: opt back in if you cannot convert to async yet.
        optionsBuilder.ConfigureWarnings(w =>
            w.Ignore(Microsoft.EntityFrameworkCore.Diagnostics.CoreEventId.SyncAndAsyncNotSupported));
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking Change #2: Cosmos discriminator property renamed from
        // "Discriminator" to "$type" in EF Core 9. Existing documents still
        // store "Discriminator". Fix: explicitly configure the old property name.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

